import test;

fn main() -> int {
    mut a: int = 10;
    mut b: int = 20;
    mut max_val: int = 0;

    if (a > b) {
        max_val = a;
    } else {
        max_val = b;
    }

    test::assert(max_val == 20, "max_val should be 20, ensuring if-else parses without trailing semicolons");

    mut i: int = 0;
    while i < 5 {
        i = i + 1;
    }

    test::assert(i == 5, "while loop should run 5 times and not require a semicolon after the block");

    return 0;
}

import test;

struct Inner {
    val: int
}

struct Outer {
    inner: Inner
}

fn main(): int {
    mut o: Outer = Outer{};
    o.inner.val = 42;

    // Assigning deeply nested dynamically evaluated L-Value
    o.inner.val = 100;

    test::assert(o.inner.val == 100, "L-value chained struct assignment failed");

    return 0;
}

import test;
// A local may share a function's name as long as the name is not CALLED in its
// scope (see fail_call_shadowed_by_local_variable.tr); other scopes still call
// the function normally.
fn helper(): int { return 7; }

fn main(): string {
    test::assert(helper() == 7, "function call outside the shadow");
    if (true) {
        immut helper: int = 3;
        test::assert(helper == 3, "variable read");
    }
    test::assert(helper() == 7, "function call after the shadow ends");
    return 0;
}

