import test;
fn main(): int {
    mut x: int = 2;
    mut result: int = 0;

    // Multi-value stacked matches — all share one body
    compare x {
        matches 1:
        matches 2:
        matches 3:
        result = 100;
        done

        otherwise:
        result = 999;
    }
    test::assert(result == 100, "stacked matches: x=2 should hit shared body");

    mut y: int = 5;
    mut result2: int = 0;
    compare y {
        matches 1:
        case 2:
        matches 3:
        result2 = 100;
        done
        otherwise:
        result2 = 200;
    }
    test::assert(result2 == 200, "stacked matches: x=5 should hit otherwise");

    return 0;
}

import test;

fn main(): int {
    auto x = 5;
    mut iterations: int = 0;

    do {
        x = x - 1;
        iterations = iterations + 1;
    } while (x > 0);

    test::assert(x == 0, "");
    test::assert(iterations == 5, "");

    return 0;
}

import test;

// Key difference from while: the condition is checked AFTER the body, so the
// body must run exactly once even though the condition is already false
// before the loop starts.
fn main(): int {
    mut x: char = 0;
    mut ranCount: int = 0;

    do {
        ranCount = ranCount + 1;
    } while (x > 0);

    test::assert(ranCount == 1, "");

    return 0;
}

import test;

// Regression test (Issue #180 follow-up): parens are optional even for
// compound/complex conditions (&&, ||) -- they only exist for grouping, same
// as every other conditional in Turf. Exercises both styles side by side so
// a regression that only fixes the "simple condition, no parens" case (but
// not compound conditions, or breaks parenthesized conditions) is caught.
fn main(): int {
    mut a: int = 0;
    mut b: int = 10;

    // No parens, compound condition.
    do {
        a = a + 1;
        b = b - 1;
    } while a < 5 && b > 0;
    test::assert(a == 5, "");
    test::assert(b == 5, "");

    // Parens still work when the caller wants them for grouping/readability.
    mut c: int = 0;
    do {
        c = c + 1;
    } while (c < 3 or c < 1);
    test::assert(c == 3, "");

    // Parens used purely for grouping precedence inside the condition.
    mut d: int = 0;
    mut finished: bool = false;
    do {
        d = d + 1;
        if d == 4 {
            finished = true;
        }
    } while (d < 10) && !finished;
    test::assert(d == 4, "");

    return 0;
}

