// `r[i]` on a `&T[N]` indexes the array the reference points at, with the
// array's own bounds check. It used to index the reference itself as if it
// were a raw pointer to whole arrays. Any other `&T` is one element: `r[0]`.

import test;

struct P {
    x: int
}

fn make(): &int[3] {
    mut a: int[3] = [1, 2, 3];
    return heap(a);
}

fn point(v: int): P {
    mut o: P = P::default();
    o.x = v;
    return o;
}

fn make_points(): &P[2] {
    mut a: P[2] = [point(4), point(7)];
    return heap(a);
}

fn sum(r: &int[3]): int {
    mut t: int = 0;
    for i in 0..3 {
        t += r[i];
    }
    return t;
}

fn bump(c: &int): void {
    c[-1] = c[0] + 1;
}

fn main(): int {
    mut n: char = 41;
    bump(&n);
    test::assert(n == 42, "a scalar reference is one element");

    mut r: &int[3] = make();
    test::assert(r[1] == 2, "read through the reference");
    r[2] = 9;
    r[0] += 5;
    test::assert(r[2] == 9 && r[0] == 6, "write through the reference");
    test::assert(r[-1] == 9, "negative index counts from the end");

    mut q: &P[2] = make_points();
    q[0].x = 11;
    test::assert(q[0].x == 11 && q[1].x == 7, "struct elements through the reference");

    mut local: int[3] = [10, 20, 30];
    test::assert(sum(&local) == 60, "a reference to a local array");
    return 0;
}

// `sizeof(void)` is rejected (fail_sizeof_void.tr) because `void` has no
// size, but a `void*` is an ordinary pointer and has one. Pins that the
// rejection did not spread to the pointer spelling.
import tset;

fn main(): int {
    test::assert(sizeof(void*) == sizeof(int*), "void* is as big as any pointer");
    test::assert(sizeof(void*) == 8, "pointers are 8 bytes");
    return 0;
}

// An array element nothing wrote is its type's default, and a `string`'s is
// "": it was a null pointer, and `a[1].length()` segfaulted (owner decision
// 2026-10-12, found by turf-fuzz). The same for a string field inside a
// struct element, and for a large array (filled in a loop).

import test;

struct P {
    string name,
    n: int
}

fn main(): int {
    mut a: string[3];
    a[0] = "x";
    test::assert(a[1].length() == 0, "an unwritten string element is empty");
    test::assert(a[2] == "", "and equal to the empty string");

    mut b: P[2];
    b[0] = P::default();
    test::assert(b[1].name == "", "a string field inside an element is empty");

    mut big: string[100000];
    big[5] = "y";
    test::assert(big[99999] == "", "the last element of a big array");
    test::assert(big[5] == "y", "a written element keeps its value");
    return 0;
}

