// Regression test: TYPE-002 S13b -- completion criterion 2, "List<Big>
// (24-byte struct) compiles, runs, prints correctly." Before this session,
// this exact shape (a generic struct instantiated with a >8-byte struct
// type argument) ICEd with "Invalid bitcast: bitcast %Big %x4 to ptr" --
// Type Erasure could only ever stuff a value into one 8-byte pointer-sized
// slot. S13a gave every instantiation its own real TurfStructType/LLVM
// layout; S13b is what makes Codegen actually USE it (killing
// FieldAccessExprAST's GenericType->base-name collapse, getLLVMType()'s
// matching collapse, and CastToType's struct passthrough) instead of still
// silently falling back to the shared, erasure-sized layout.
import list::List;
import test;

struct Big {
    a: int,
    b: int,
    c: int
}

fn Big.new(a: int, b: int, c: int): void {
    self.a = a;
    self.b = b;
    self.c = c;
}

// A >8-byte struct round-tripping through a generic FREE function -- this
// half was already real since S12a (free-function monomorphization doesn't
// depend on struct LAYOUT at all, only on the argument/return TYPES being
// substituted concretely), verified here rather than assumed.
fn<T> identity(x: T): T {
    return x;
}

// A generic struct instantiated as a >8-byte-carrying STRUCT FIELD of
// another (non-generic) struct -- proves the round-trip works through
// struct field storage too, not just a bare local variable.
struct Holder {
    items: List<Big>
}

fn main(): int {
    // List<Big> itself: push/pop/length with a real, concrete 24-byte
    // struct value and return type (verified live via --emit-llvm during
    // this session: `turf_List.push_gen1_Big...(ptr %self, %Big %item)`
    // and `turf_List.pop_gen1_Big...(ptr %self): %Big` -- genuinely
    // struct-shaped LLVM types, not erased pointers).
    mut l: List<Big> = List::default();
    l.push(Big::new(1, 2, 3));
    l.push(Big::new(4, 5, 6));
    test::assert(l.length() == 2, "List<Big>.length() wrong");
    mut popped: Big = l.pop();
    test::assert(popped.a == 4 && popped.b == 5 && popped.c == 6,
        "List<Big>.pop() wrong");
    mut first: Big = l.get(0);
    test::assert(first.a == 1 && first.b == 2 && first.c == 3,
        "List<Big>.get(0) wrong");

    // Generic free function, >8-byte struct argument/return.
    mut echoed: Big = identity(Big::new(7, 8, 9));
    test::assert(echoed.a == 7 && echoed.b == 8 && echoed.c == 9,
        "identity<Big> wrong");

    // Generic struct instantiation as ANOTHER struct's own field.
    mut h: Holder = Holder::default();
    h.items = List();
    h.items.push(Big::new(10, 20, 30));
    test::assert(h.items.length() == 1, "Holder.items (List<Big>) wrong");
    mut fromField: Big = h.items.get(0);
    test::assert(fromField.a == 10 && fromField.b == 20 && fromField.c == 30,
        "Holder.items.get(0) wrong");

    return 0;
}

// A generic method declared in THIS file on a generic struct imported from
// the stdlib (`fn<T> List.lastOr(...)` on `list::List<T>`): a template the
// monomorphizer clones once per instantiation, exactly like list.tr's own
// methods. Used at two instantiations whose `T` has different sizes and
// representations, so a shared or mis-substituted clone would read the
// wrong element.
//
// The version WITHOUT `<T>` used to crash at its first call ("Internal
// error: no generic method declaration found ... during monomorphization")
// and is now rejected at the declaration --
// fail_method_on_generic_struct_without_type_params.tr and
// tests/07_functions_modules/fail_method_on_imported_generic_struct_without_type_params.tr.

import test;
import list::List;

fn<T> List.lastOr(fallback: T): T {
    if (self.length() == 0) {
        return fallback;
    }
    return self.get(self.length() - 1);
}

fn<T> List.doubledLength(): int {
    return self.length() * 2;
}

fn main(): int {
    mut ints: List<int> = List::default();
    test::assert(ints.lastOr(-1) == -1, "empty List<int> falls back");
    ints.push(10);
    ints.push(20);
    test::assert(ints.lastOr(-1) == 20, "List<int> last element");
    test::assert(ints.doubledLength() == 4, "List<int> method with no T in its signature");

    mut strs: List<string> = List{};
    strs.push("a");
    strs.push("b");
    strs.push("c");
    test::assert(strs.lastOr("none") == "c", "List<string> last element");
    test::assert(strs.doubledLength() == 6, "List<string> second instantiation");
    return 0;
}

// Regression test: OVH-007 (docs/planning/OVERHAUL_REMAINING_WORK.md) --
// chained field access through a nested generic struct field.
//
// Root cause: Codegen has its OWN, independent type-inference function,
// getExprType() (CodegenCore.cpp), separate from the TypeChecker's own
// (already-correct) inference. getExprType()'s FieldAccess case recovers a
// generic struct's own type-parameter substitution (T -> int, for a
// `Box<int>`-typed base) by scanning the struct's fields for a
// TurfGenericParamType/NamedType/pointer/array shape and rebuilding the
// field's type through that substitution -- but had no case at all for a
// field whose OWN declared type is ANOTHER generic instantiation
// (`struct Box<T> { inner: Pair<T, T> }`), so `b.inner`'s type came back as
// the literal, still-open `Pair<T, T>` instead of `Pair<int, int>`.
// `b.inner.a`'s own FieldAccessExprAST::codegenLValue() then tried to
// resolve `Pair<T, T>` to a real registered clone via its mangled
// instantiation name -- built from the UNSUBSTITUTED `T, T` -- which
// matches nothing the monomorphizer ever actually registered (it registers
// `Pair<int, int>`, not `Pair<T, T>`), so the lookup failed and fell
// through to "Cannot access field on non-struct type".
//
// Verified live before this fix:
// ```turf
// struct Pair<A, B> { a: A, b: B }
// struct Box<T> { inner: Pair<T, T> }
// fn main(): int { mut b: Box<int> = Box::default(); b.inner.a = 3; return b.inner.a - 3; }
// // error: Cannot access field on non-struct type
// ```
// Going through a local (`mut p: Pair<int, int> = b.inner; p.a = 3;`)
// already worked -- the bug was specifically in resolving the type of
// `b.inner` when it is itself used as the BASE of a further field access.
import test;

struct Pair<A, B> { a: A, b: B }
struct Box<T> { inner: Pair<T, T> }
struct Wrap<T> { boxed: Box<T> }

fn<T> Box.getA(): T { return self.inner.a; }
fn<T> Box.setA(v: T): void { self.inner.a = v; }

fn main(): int {
    mut b: Box<int> = Box::default();

    // Read through a chained field access.
    b.inner.a = 3;
    test::assert(b.inner.a == 3, "b.inner.a should read back 3 after a direct write");

    // Write the OTHER field of the same nested struct.
    b.inner.b = 7;
    test::assert(b.inner.b == 7, "b.inner.b should read back 7");
    test::assert(b.inner.a == 3, "b.inner.a should be unaffected by writing b.inner.b");

    // Compound-assign through the chain.
    b.inner.a += 10;
    test::assert(b.inner.a == 13, "b.inner.a += 10 should update through the chain");

    // Three levels deep (Wrap<int> -> Box<int> -> Pair<int,int> -> int).
    mut w: Wrap<int> = Wrap::default();
    w.boxed.inner.a = 42;
    test::assert(w.boxed.inner.a == 42, "three-level chained write should read back correctly");
    w.boxed.inner.a += 1;
    test::assert(w.boxed.inner.a == 43, "three-level chained compound-assign should update correctly");

    // Through a method's own `self` -- both a read and a write.
    b2 := Box::default();
    b2.setA(5);
    test::assert(b2.getA() == 5, "Box<int>.setA(5) then .getA() should round-trip through self.inner.a");
    test::assert(b2.inner.a == 5, "the write through self.inner.a should be externally visible too");

    return 0;
}

// Regression test: OVH-009 -- `>>` (and `>>=`) closing nested generic type
// arguments with no space must parse, not hit "Expected '>' or ',' in
// generic type" (plus the misleading cascade "Statements are not allowed
// outside of a function"). The lexer's maximal munch (INV-LEX-1, never
// special-cased there) fuses adjacent '>'-family characters into one token
// regardless of context -- ParseType()'s generic-argument-list closing
// check is what splits one logical '>' off such a token, working whether
// it's a bare `>>`, or a `>>`/`>=` immediately followed by more source
// (another closing '>', or the '=' of an assignment).
//
// The existing spaced workaround (`List<List<Big> >`,
// 16_nested_generic_struct_field.tr) is left untouched by this fix and
// must keep passing unchanged -- both spellings are legal now.

import list::List;
import map::Map;
import test;

fun main(): int {
    // `>>` closing two levels with no space.
    mut ll: List<List<int>> = List::default();
    mut inner: List<int> = List::default();
    inner.push(1);
    inner.push(2);
    ll.push(inner);
    test::assert(ll.get(0).get(1) == 2, "List<List<int>> round-trip");

    // `>>` closing a generic argument that is itself the SECOND type
    // parameter of a different generic struct (`Map<K, List<V>>`).
    mut m: Map<string, List<int>> = Map::default();
    mut v: List<int> = List::default();
    v.push(42);
    m.put("k", v);
    test::assert(m.get("k").get(0) == 42, "Map<string, List<int>> round-trip");

    // `>>>` -- three closers with no space, lexed as TOK_RSHIFT ('>>') then
    // a plain '>', never a dedicated triple-'>' token.
    mut lll: List<List<List<int>>> = List::default();
    mut mid: List<List<int>> = List::default();
    mut leaf: List<int> = List::default();
    leaf.push(7);
    mid.push(leaf);
    lll.push(mid);
    test::assert(lll.get(0).get(0).get(0) == 7, "List<List<List<int>>> round-trip");

    // `>>=` -- two closers immediately followed by '=' with no space, the
    // lexer's single TOK_RSHIFT_ASSIGN token, split into '>' + '>' + '='.
    mut m2: Map<string, List<int>>= Map::default();
    mut v2: List<int> = List::default();
    v2.push(9);
    m2.put("k2", v2);
    test::assert(m2.get("k2").get(0) == 9, "'>>=' after nested generic close still assigns");

    return 0;
}

