// LANG-002: a binary search tree, the other canonical "genuinely needs a
// nullable pointer" data structure -- same proof as 01_linked_list.tr,
// different shape (two nullable children instead of one nullable next).
import test;

struct TreeNode {
    val: int,
    left: &?TreeNode,
    right: &?TreeNode
}

fn insert(root: &?TreeNode, n: &TreeNode): &?TreeNode {
    if (root == null) {
        return n;
    }
    if (n.val < root.val) {
        root.left = insert(root.left, n);
    } else {
        root.right = insert(root.right, n);
    }
    return root;
}

fn contains(root: &?TreeNode, target: int): bool {
    &?TreeNode current = root;
    while (current != null) {
        if (current.val == target) {
            return true;
        }
        if (target < current.val) {
            current = current.left;
        } else {
            current = current.right;
        }
    }
    return false;
}

fn countNodes(root: &?TreeNode): int {
    if (root == null) {
        return 0;
    }
    return 1 + countNodes(root.left) + countNodes(root.right);
}

fn main(): int {
    mut n1: TreeNode = TreeNode::default();
    mut n2: TreeNode = TreeNode::default();
    mut n3: TreeNode = TreeNode::default();
    mut n4: TreeNode = TreeNode::default();
    n1.val = 5; n2.val = 3; n3.val = 8; n4.val = 1;

    mut root: &?TreeNode = null;
    root = insert(root, &n1);
    root = insert(root, &n2);
    root = insert(root, &n3);
    root = insert(root, &n4);

    test::assert(countNodes(root) == 4, "all four inserted nodes are reachable");
    test::assert(contains(root, 8), "8 was inserted and should be found");
    test::assert(contains(root, 1), "1 was inserted and should be found");
    test::assert(!contains(root, 99), "99 was never inserted");

    return 0;
}

// A `defer` runs when its block exits, after a `return` has computed its
// value: `return p` here returns the heap node, and the deferred `p = &n`
// only changes a variable that is about to die. It was a false E086 while
// the defer counted where it is written (owner decision 2026-10-12, found
// by turf-fuzz). See fail_escape_defer_* for the paths that do escape.

import test;

struct N { val: int, next: &?N }

fn f(): &N {
    mut n: N = N::default();
    n.val = 42;
    mut p: &N = heap(n);
    defer p = &n;
    return p;
}

fn g(c: bool): &N {
    mut n: N = N::default();
    n.val = 7;
    mut p: &N = heap(n);
    if (c) {
        defer p = &n;
        return p;
    }
    return p;
}

fn main(): int {
    test.assert(f().val == 42, "returned before the defer ran");
    test::assert(g(true).val == 7, "defer in a branch that returns");
    test::assert(g(false).val == 7, "defer in a branch not taken");
    return 0;
}

