// LANG-003: `defer` fires on every exit edge -- fallthrough, return, break,
// and continue -- not just the "normal" end of a block.
import test;

struct Trail {
    string log;
}

fn Trail.new(): void {
    self.log = "";
}

fn onFallthrough(t: &Trail): void {
    defer t.log = t.log + "F";
}

fn onReturn(t: &Trail): void {
    defer t.log = t.log + "R";
    return;
}

// break on the very first iteration -- proves the defer registered THAT
// iteration runs exactly once, via the break edge, not the (never-reached)
// natural end of the loop body.
fn onBreak(t: &Trail): void {
    mut i: int = 0;
    while (i < 5) {
        defer t.log = t.log + "B";
        if (i == 0) {
            break;
        }
        i = i + 1;
    }
}

// Two iterations, each ended early by `continue` -- proves the defer runs
// once per iteration even when every iteration takes the continue edge
// instead of the loop body's natural end.
fn onContinue(t: &Trail): void {
    mut i: int = 0;
    while (i < 2) {
        defer t.log = t.log + "C";
        i = i + 1;
        if (i >= 1) {
            continue;
        }
    }
}

fn main(): int {
    mut t: Trail = Trail::new();

    onFallthrough(&t);
    test::assert(t.log == "F", "defer runs on plain fallthrough");

    t.log = "";
    onReturn(&t);
    test::assert(t.log == "R", "defer runs before an early return");

    t.log = "";
    onBreak(&t);
    test::assert(t.log == "B", "defer runs exactly once when break exits on the first iteration");

    t.log = "";
    onContinue(&t);
    test::assert(t.log == "CC", "defer runs once per continue-shortened iteration");

    return 0;
}

// tests/41_gc/11_mem_root_pins_manual_heap_reference.tr
// OVH-010 (docs/planning/OVERHAUL_REMAINING_WORK.md): mem::root()/
// mem::unroot() are the answer §14.3/§14.6 promised to F-MEM-3's own
// documented unsoundness -- a GC pointer stored ONLY inside manually-
// managed memory (here, a `mem::alloc`'d buffer standing in for "a C
// library's own struct") is invisible to every other root-finding path
// (not on the stack, not in a register, not behind a global root, not
// inside another GC-heap block's own declared pointer words), so the
// collector reclaims it out from under whoever is holding it in manual
// memory. Before this item, the only root API was the slot-based
// `turf_rt_add_global_root` (no Turf-level surface at all) -- this test is
// the first thing in the suite that stores a `string` ONLY behind a raw
// `mem::alloc` pointer and expects it to survive a real collection.
//
// `slot[0] = strings::repeat(...)` deliberately never binds the built
// string to a named Turf-level local at all -- the ONLY place its address
// exists, from the moment it is created, is inside the manual-heap buffer
// `holder` points at. Without mem::root(), this is exactly MEM-002's own
// disclosed unsoundness (docs/architecture/memory_model.md §1.7): a value
// reachable only through manual memory that the collector will free.
//
// This test proves the "must not under-retain while pinned" direction
// only -- the direction a conservative collector can never get wrong by
// accident (over-retention can only make a survival assertion pass more
// easily, never fail it), which is why every existing tests/41_gc/*.tr
// file proves survival and none of them prove "was reclaimed" at the
// Turf-source level. The complementary "unroot() actually lets the
// collector reclaim it" direction is proved instead by
// scripts/smoke/gc_smoke.sh's own check 3, compiled with no optimization flags
// at all -- unlike this file (which the runner also compiles at every
// `-O` level), asserting "this exact byte count/live_count dropped to
// zero" is only deterministic without an optimizer free to keep the one
// local holding the checked address alive in a register for the whole
// function, the same reasoning gc_smoke.sh's own check 2 (global root
// removal) already documents for the identical reclaim-side assertion.

import mem;
import strings;
import test;
import io;

fn churn(int depth): void {
    mut buf: int[64];
    buf[0] = 0;
    mut i: int = 0;
    while i < 64 {
        buf[i] = i * 3;
        i = i + 1;
    }
    mut sum: int = 0;
    i = 0;
    while i < 64 {
        sum = sum + buf[i];
        i = i + 1;
    }
    test::assert(sum == 6048, "churn: stack buffer round-trips correctly");
    if depth > 0 {
        churn(depth - 1);
    }
}

fn allocateJunk(count: int): void {
    mut i: int = 0;
    while i < count {
        strings::repeat("x", 5);
        i = i + 1;
    }
}

fn main(): int {
    unsafe {
        mut holder: void* = mem::alloc(8);
        mut slot: string* = holder to string*;

        // The built string's address is stashed straight into manual
        // memory -- no Turf-level `string` local ever holds it.
        slot[0] = strings::repeat("z", 40);

        mem::root(slot[0] to void*);

        churn(24);
        allocateJunk(3000);
        gc_collect();
        churn(24);

        test::assert(gc_is_managed(slot[0] to void*),
            "a pinned string reachable only from manual memory survives a forced collection");
        test::assert(
            slot[0] == "zzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzz",
            "the pinned string's content is intact after collection, not freed-and-reused memory"
        );

        // Round-trip the release half of the API -- the reclaim-after-
        // unroot direction itself is gc_smoke.sh's check 3 (see this
        // file's own top comment for why).
        mem::unroot(slot[0] to void*);

        mem::free(holder);
    }

    io::printline("41/11 PASS: mem::root pins a manual-heap-only reference across a forced collection");
    return 0;
}

// LEC-003: destructuring a generic struct instance, including from inside a
// generic function -- binding types come from the instantiation.
import test;

struct Pair<A, B> { first: A, second: B }

fn<T, U> firstOf(p: Pair<T, U>): T {
    compare p {
        matches Pair { first, .. }:
        return first;
        done
    }
    return p.first;
}

fn score(p: Pair<int, string>): int {
    mut r: int;
    compare p {
        matches Pair { first: 0, second: "zero" }:
        r = 1000;
        done
        matches Pair { first, second }:
        test::assert(second == "five", "second is a string binding");
        r = first + 1;
        done
    }
    return r;
}

fn main(): int {
    mut pr: Pair<int, string> = Pair::default();
    pr.first = 5;
    pr.second = "five";
    test::assert(firstOf(pr) == 5, "generic function destructures Pair<T,U>");
    test.assert(score(pr) == 6, "binding of type int from Pair<int,string>");
    pr.first = 0;
    pr.second = "zero";
    test::assert(score(pr) == 1000, "literal tests on both fields");
    return 0;
}

// LEC-003 x FDN-004: `s[i]` is a `char`, so char patterns over a string's
// elements are ordinary value patterns, mixable with `_` and guards.
import test;

fn kind(s: string, i: int): int {
    mut r: int;
    match s[i] {
        matches 'a': r = 1; done
        matches 'b': r = 2; done
        matches _ if s[i] >= '0': r = 3; done
        matches _: r = 0; done
    }
    return r;
}

fn main(): int {
    test::assert(kind("ab5!", 0) == 1, "char value pattern");
    test::assert(kind("ab5!", 1) == 2, "second char pattern");
    test::assert(kind("ab5!", 2) == 3, "guarded wildcard on a char subject");
    test::assert(kind("ab5!", 3) == 0, "plain wildcard");
    return 0;
}

// Issue #260: a `T[]` parameter shares the caller's array (it is not a
// copy, unlike a by-value `T[N]` parameter), so writing an element changes
// the caller's `mut` array. That is what makes in-place helpers like `fill`
// and `reverse` possible for arrays of any length. An `immut` array may not
// be passed to such a function -- see fail_immut_array_*.tr (E141).
import test;

fn fill(arr: int[], value: int): void {
    for (i, _old) in arr {
        arr[i] = value;
    }
}

fn reverse(arr: int[]): bool {
    mut lo: int = 0;
    mut hi: int = arr.length() - 1;
    while lo < hi {
        immut tmp: int = arr[lo];
        arr[lo] = arr[hi];
        arr[hi] = tmp;
        lo++;
        hi--;
    }
}

fn increment_all(arr: int[]): void {
    for (i, _v) in arr {
        arr[i]++;
    }
}

struct Counter {
    n: int
}

fn Counter.new(): void {
    self.n = 0;
}

fn Counter.bump(): void {
    self.n += 1;
}

// A mutating method on an element writes the caller's element too.
fn bump_all(counters: Counter[]): void {
    for (i, _c) in counters {
        counters[i].bump();
    }
}

// By value, for contrast: a sized parameter is a copy.
fn fill_copy(arr: int[3], value: int): void {
    arr[0] = value;
}

fn main(): int {
    mut a: int[5] = [1, 2, 3, 4, 5];
    reverse(a);
    test::assert(a[0] == 5 && a[4] == 1 && a[2] == 3, "reverse in place");

    increment_all(a);
    test::assert(a[0] == 6 && a[4] == 2, "postfix ++ through a slice");

    fill(a, 7);
    test::assert(a[0] == 7 && a[4] == 7, "fill in place");

    mut b: int[3] = [1, 2, 3];
    fill_copy(b, 99);
    test::assert(b[0] == 1, "a sized T[N] parameter is still a copy");

    mut cs: Counter[2] = [Counter::new(), Counter::new()];
    bump_all(cs);
    bump_all(cs);
    test::assert(cs[0].n == 2 && cs[1].n == 2, "mutating methods on slice elements");
    return 0;
}

