// `@ownership(...)` is carried through the front end in every valid shape: on an
// `extern fn` (raw pointers only appear in extern signatures), stacked, and
// before `pub`. Declaring ownership changes nothing about how a program
// compiles or runs.

import test;

@ownership(acquires)
extern fn take_block(size: int): void*;

@ownership(releases: block)
extern fn give_block_back(block: void*): void;

@ownership(acquires)
@ownership(releases: old
pub extern fn resize_block(old: void*, size: int): void*;

fn main(): int {
    test::assert(1 + 1 == 2, "annotated declarations do not disturb compilation");
    return 0;
}

// LEC-009 (F-COLL-1): Stack and Queue follow the List rule -- `=` and passing
// share one header, `.copy()` is independent. A Queue copy keeps the order
// after its head has moved (elements are copied from `head`, not from 0).
import queue::Queue;
import stack::Stack;
import test;

fn push_two(s: Stack<int>): void {
    s.push(1);
    s.push(2);
}

fn drain_one(q: Queue<int>): int {
    return q.dequeue();
}

fn main(): int {
    mut s: Stack<int> = Stack.default();
    push_two(s);
    test::assert(s.length() == 2 && s.peek() == 2, "callee push on a stack");
    mut s2: Stack<int> = s;
    test::assert(s2.pop() == 2 && s.length() == 1, "stack alias pop");
    mut sc: Stack<int> = s.copy();
    sc.push(9);
    test::assert(s.length() == 1 && sc.length() == 2 && sc.peek() == 9, "stack copy");

    mut q: Queue<int> = Queue::default();
    q.enqueue(1);
    q.enqueue(2);
    q.enqueue(3);
    test::assert(drain_one(q) == 1 && q.length() == 2, "callee dequeue on a queue");
    mut qc: Queue<int> = q.copy();
    test::assert(qc.dequeue() == 2 && qc.dequeue() == 3, "queue copy keeps the order after head moved");
    test::assert(q.length() == 2 && q.peek() == 2, "the original is untouched");
    mut q2: Queue<int> = q;
    q2.enqueue(4);
    test::assert(q.length() == 3, "queue alias enqueue");
    return 0;
}

// Nodes reachable only through an array of references -- on the stack, in a
// heap struct's field, or in a `.copy()` on the GC heap -- survive collection.
// Run under TURF_GC_STRESS=1 / TURF_GC_VALIDATE=1 as well (AGENTS.md).
import test;

struct N { val: int, next: &?N }

struct Box { xs: (&N)[3], k: int }

fn mk(v: int): &N {
    mut n: N = N::default();
    n.val = v;
    return heap(n);
}

fn churn(): int {
    mut t: int = 0;
    for i in range(0, 200) {
        mut junk: &N = mk(i);
        t = t + junk.val;
    }
    return t;
}

fn main(): int {
    mut a: (&N)[3] = [mk(1), mk(2), mk(3)];
    mut b: &Box = heap(Box::default());
    b.xs[0] = mk(10);
    b.xs[1] = mk(20);
    b.xs[2] = mk(30);
    mut c: (&N)[] = a.copy();
    churn();
    churn();
    mut t: int = 0;
    for x in a {
        t = t + x.val;
    }
    for x in b.xs {
        t = t + x.val;
    }
    for x in c {
        t = t + x.val;
    }
    test::assert_eq(t, 72, "every node is still reachable");
    return 0;
}
